func (m *pageMap) reverseLookupName(p *pageState) (string, bool) {
	var pathInfo *paths.Path
	var metaLang string
	var metaLangIndex int
	if f := p.File(); f != nil {
		fi := f.FileInfo()
		if fi == nil {
			return "", false
		}
		meta := fi.Meta()
		if meta == nil {
			return "", false
		}
		pathInfo = meta.PathInfo
		if pathInfo == nil {
			return "", false
		}
		metaLang = meta.Lang
		metaLangIndex = meta.LangIndex
	} else {
		// No file backing, e.g. a page created by a content adapter.
		pi := p.PathInfo()
		if pi == nil {
			return "", false
		}
		if pi.Lang() != "" && pi.Lang() != m.cfg.lang {
			return "", false
		}
		pathInfo = pi
	}

	name := pathInfo.NameNoIdentifier()
	if pathInfo.IsBundle() {
		name = pathInfo.Container()
	}
	belongsToSite := metaLang == m.cfg.lang || metaLang == "" || pathInfo.Lang() == m.cfg.lang
	belongsToPartition := metaLangIndex == m.i || pathInfo.Lang() == ""
	if pathInfo.IsBundle() && (belongsToSite || belongsToPartition) {
		name = pathInfo.Container()
	}
	return name, true
}

