func (m *pageMap) reverseLookupName(p *pageState) (string, bool) {
	var pathInfo *paths.Path
	var metaLang string
	var metaLangIndex int
	if f := p.File(); f != nil {
		fi := f.FileInfo()
		if fi == nil {
			return "", false
		}
		meta := fi.Meta()
		if meta == nil {
			return "", false
		}
		pathInfo = meta.PathInfo
		if pathInfo == nil {
			return "", false
		}
		metaLang = meta.Lang
		metaLangIndex = meta.LangIndex
		if p.m.pageConfig.IsFromContentAdapter {
			// The file above is the _content.gotmpl data file backing this page.
			// Use the page's own path info to derive the lookup name.
			pi := p.PathInfo()
			if pi == nil {
				return "", false
			}
			pathInfo = pi
		}
	} else {
		// No file backing, e.g. a standalone page.
		pi := p.PathInfo()
		if pi == nil {
			return "", false
		}
		if pi.Lang() != "" && pi.Lang() != m.cfg.lang {
			return "", false
		}
		pathInfo = pi
	}

